-- Append-only audit of management market enable/disable changes.
CREATE TABLE leadgen.research_market_registry_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  market_code text NOT NULL REFERENCES leadgen.research_market_registry(market_code) ON DELETE RESTRICT,
  previous_status text NOT NULL,
  previous_search_enabled boolean NOT NULL,
  status text NOT NULL CHECK(status IN('ACTIVE','INACTIVE','HIDDEN')),
  search_enabled boolean NOT NULL,
  actor text NOT NULL CHECK(btrim(actor)<>''),
  actor_role text NOT NULL CHECK(btrim(actor_role)<>''),
  change_reason text NOT NULL CHECK(btrim(change_reason)<>''),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX research_market_registry_events_market_idx ON leadgen.research_market_registry_events(market_code,created_at DESC);
CREATE FUNCTION leadgen.guard_research_market_registry_event() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Market registry events are append-only'; END; $$;
CREATE TRIGGER research_market_registry_event_immutable BEFORE UPDATE OR DELETE ON leadgen.research_market_registry_events
  FOR EACH ROW EXECUTE FUNCTION leadgen.guard_research_market_registry_event();

-- Migration 029 limited Phase 9 cohort items to AE/MX; any registry market code is now valid.
ALTER TABLE leadgen.research_job_cohort_items
  DROP CONSTRAINT research_job_cohort_items_market_code_check,
  ADD CONSTRAINT research_job_cohort_items_market_code_check CHECK(market_code ~ '^[A-Z]{2}$');

-- Data-driven categories --------------------------------------------------
-- Category aliases may now be recorded in every search vocabulary language (024/030 allowed en/es/zh/und).
ALTER TABLE leadgen.dpv_product_category_scope_aliases
  DROP CONSTRAINT dpv_product_category_scope_aliases_language_check,
  ADD CONSTRAINT dpv_product_category_scope_aliases_language_check
    CHECK(language IN('en','es','zh','de','fr','pt','it','tr','ar','und'));
ALTER TABLE leadgen.product_taxonomy_aliases
  DROP CONSTRAINT product_taxonomy_aliases_language_check,
  ADD CONSTRAINT product_taxonomy_aliases_language_check
    CHECK(language IN('en','es','zh','de','fr','pt','it','tr','ar','und'));

COMMIT;
